                addTransitionType('add-video-forward');
              }
              setShowItem((prev) => !prev);
            });
          }}>
          ➡️
        </button>
      </div>
      {showItem ? <Item /> : null}
    </>
  );
}
```

Corresponding CSS:

```css
::view-transition-old(.slide-in-back) {
  animation-name: slideOutRight;
  animation-duration: 500ms;
  animation-timing-function: ease-in-out;
}

::view-transition-new(.slide-in-back) {
  animation-name: slideInRight;
  animation-duration: 500ms;
  animation-timing-function: ease-in-out;
}

::view-transition-old(.slide-in-forward) {
  animation-name: slideOutLeft;
  animation-duration: 500ms;
  animation-timing-function: ease-in-out;
}

::view-transition-new(.slide-in-forward) {
  animation-name: slideInLeft;
  animation-duration: 500ms;
  animation-timing-function: ease-in-out;
}

@keyframes slideOutLeft {
  from { transform: translateX(0); opacity: 1; }
  to { transform: translateX(-100%); opacity: 0; }
}

@keyframes slideInLeft {
  from { transform: translateX(-100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

@keyframes slideOutRight {
  from { transform: translateX(0); opacity: 1; }
  to { transform: translateX(100%); opacity: 0; }
}

@keyframes slideInRight {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}
```

### Types are also available in JS event callbacks

Events receive `(instance, types)` where `types` is an `Array<string>` of Transition Types (empty if none specified):

```js
 <ViewTransition
  onEnter={(instance, types) => {
    const duration = types.includes('fast') ? 150 : 2000;
    const anim = instance.new.animate(
      SLIDE_IN,
      {duration: duration, easing: 'ease-out'}
    );
    return () => anim.cancel();
  }}
>
```

### Router note

> "React will skip animations from popstate and animations won't run for the back button. You can fix this by upgrading your router to use the Navigation API."
> Also: if Navigation is blocked on React, "your router must unblock in `useLayoutEffect` since `useEffect` would lead to a deadlock."

---

## 5. `prefers-reduced-motion`

> ### Always check `prefers-reduced-motion`
>
> "Many users may prefer not having animations on the page. **React doesn't automatically disable animations for this case.**
>
> We recommend always using the `@media (prefers-reduced-motion)` media query to disable animations or tone them down based on user preference.
>
> In the future, CSS libraries may have this built-in to their presets."

There is no built-in prop for this — it must be handled in your CSS, e.g. by guarding your View Transition Class rules:

```css
@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(.slide-in),
  ::view-transition-new(.slide-in) {
    animation: none;
  }
}
```

---

## Bonus: cleanup for JS-driven animations

Every View Transition Event **should return a cleanup function** so the browser can cancel interrupted animations:

```js
<ViewTransition
  onEnter={(instance) => {
    const anim = instance.new.animate(
      SLIDE_IN,
      {duration: 500, easing: 'ease-out'}
    );
    return () => anim.cancel();
  }}
>
```

Instance shape: `old`, `new`, `name`, `group`, `imagePair` (the view transition pseudo-elements). Only one event fires per `<ViewTransition>` per Transition, and **`onShare` takes precedence over `onEnter` and `onExit`.**

