@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ---------------------------------------------------------------------------
   View transitions

   Classes here are applied by the `<ViewTransition>` props in
   lib/view-transitions.ts. Every rule that produces movement lives inside
   `prefers-reduced-motion: no-preference`; the `reduce` block at the bottom
   replaces all of it with a plain cross-fade.
   --------------------------------------------------------------------------- */

/*
 * Sizing for the shared thumbnail → hero morph. The thumbnail is 4:3 and the
 * hero is 1:1, and the browser default (`block-size: auto`) keeps each snapshot
 * at its own aspect ratio, so it would drift out of the group box as the box
 * morphs. Filling the box instead keeps the two locked together. Sizing, not
 * animation, so it applies at every motion preference.
 */
::view-transition-old(.vt-product-image),
::view-transition-new(.vt-product-image) {
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
}

@media (prefers-reduced-motion: no-preference) {
  /* Shared element: grid thumbnail ⇄ detail hero. */
  ::view-transition-group(.vt-product-image),
  ::view-transition-old(.vt-product-image),
  ::view-transition-new(.vt-product-image) {
    animation-duration: 420ms;
    animation-timing-function: cubic-bezier(0.32, 0.72, 0, 1);
  }

  /* Directional page slides. The outgoing page leaves a little faster than the
     incoming one arrives, which keeps the destination feeling like it leads. */
  ::view-transition-old(.vt-slide-out-left) {
    animation: vt-exit-left 300ms cubic-bezier(0.4, 0, 1, 1) both;
  }

  ::view-transition-new(.vt-slide-in-right) {
    animation: vt-enter-right 380ms cubic-bezier(0.32, 0.72, 0, 1) both;
  }

  ::view-transition-old(.vt-slide-out-right) {
    animation: vt-exit-right 300ms cubic-bezier(0.4, 0, 1, 1) both;
  }

  ::view-transition-new(.vt-slide-in-left) {
    animation: vt-enter-left 380ms cubic-bezier(0.32, 0.72, 0, 1) both;
  }

  /* Suspense reveal: skeleton → content. */
  ::view-transition-group(.vt-reveal) {
    animation-duration: 300ms;
    animation-timing-function: cubic-bezier(0.32, 0.72, 0, 1);
  }

  ::view-transition-old(.vt-reveal) {
    animation: vt-fade-out 160ms ease-out both;
  }

  ::view-transition-new(.vt-reveal) {
    animation: vt-reveal-in 300ms cubic-bezier(0.32, 0.72, 0, 1) both;
  }
}

