import { chromium } from 'playwright'

const BASE = 'http://localhost:3123'

const INSTRUMENT = `
  window.__vt = [];
  const orig = document.startViewTransition && document.startViewTransition.bind(document);
  if (!orig) { window.__noVTApi = true; }
  else {
    document.startViewTransition = (arg) => {
      const t = orig(arg);
      const record = { animations: [], names: [] };
      window.__vt.push(record);
      t.ready.then(() => {
        record.animations = document.getAnimations().map((a) => ({
          name: a.animationName ?? null,
          pseudo: a.effect?.pseudoElement ?? null,
          duration: a.effect?.getTiming?.().duration ?? null,
        }));
        // Which elements React actually gave a view-transition-name/class to.
        record.names = [...document.querySelectorAll('[style*="view-transition-name"]')].map((el) => ({
          cls: el.getAttribute('class'),
          name: el.style.viewTransitionName,
          vtClass: el.style.viewTransitionClass,
        }));
      }).catch(() => {});
      return t;
    };
  }
`

function summarize(record) {
  const groups = record.animations.filter((a) => a.pseudo?.startsWith('::view-transition-group'))
  const olds = record.animations.filter((a) => a.pseudo?.startsWith('::view-transition-old'))
  const news = record.animations.filter((a) => a.pseudo?.startsWith('::view-transition-new'))
  const fmt = (list) => list.map((a) => `${a.pseudo!.replace('::view-transition-', '')} -> ${a.name} @${a.duration}ms`)
  return { groups: fmt(groups), old: fmt(olds), new: fmt(news), named: record.names }
}

async function run(reducedMotion) {
  const browser = await chromium.launch()
  const ctx = await browser.newContext({ reducedMotion, viewport: { width: 1280, height: 900 } })
  const page = await ctx.newPage()
  const out = { reducedMotion, steps: {} }

  await page.goto(BASE, { waitUntil: 'networkidle' })
  await page.addInitScript(INSTRUMENT)
  // addInitScript only applies to future loads; inject into the live page too.
  await page.evaluate(INSTRUMENT)

  out.noVTApi = await page.evaluate(() => !!window.__noVTApi)

  // ---- grid -> detail (forward) ----
  await page.click('.product-card:nth-child(3)')
  await page.waitForSelector('.product-hero')
  await page.waitForTimeout(1200)
  let vt = await page.evaluate(() => window.__vt)
  out.steps.forward = vt.map(summarize)

  // ---- detail -> grid (back) ----
  await page.evaluate(() => { window.__vt = [] })
  await page.click('.back-link')
  await page.waitForSelector('.product-grid')
  await page.waitForTimeout(1200)
  vt = await page.evaluate(() => window.__vt)
  out.steps.back = vt.map(summarize)

  await browser.close()
  return out
}

for (const rm of ['no-preference', 'reduce']) {
  const res = await run(rm)
  console.log('\n' + '='.repeat(78))
  console.log('prefers-reduced-motion:', rm, res.noVTApi ? '(NO startViewTransition API!)' : '')
  console.log('='.repeat(78))
  for (const [step, records] of Object.entries(res.steps)) {
    console.log(`\n--- ${step}: ${records.length} view transition(s) ---`)
    records.forEach((r, i) => {
      console.log(`  [transition ${i + 1}]`)
      console.log('    named elements:', JSON.stringify(r.named))
      console.log('    groups:', JSON.stringify(r.groups))
      console.log('    old   :', JSON.stringify(r.old))
      console.log('    new   :', JSON.stringify(r.new))
    })
  }
}

