import { chromium } from 'playwright'

const BASE = 'http://localhost:3123'

const browser = await chromium.launch()
const ctx = await browser.newContext({
  reducedMotion: 'no-preference',
  viewport: { width: 1000, height: 700 },
})
const page = await ctx.newPage()
await page.goto(BASE, { waitUntil: 'networkidle' })

// Which element carries `view-transition-name: none`?
await page.evaluate(() => {
  const orig = document.startViewTransition.bind(document)
  document.startViewTransition = (arg) => {
    const t = orig(arg)
    t.ready.then(() => {
      window.__noneEls = [...document.querySelectorAll('[style*="view-transition-name"]')].map(
        (el) => ({ tag: el.tagName, cls: el.className || null, name: el.style.viewTransitionName })
      )
    })
    return t
  }
})

await page.screenshot({ path: '/tmp/vtcheck/0-grid.png' })

// Slow everything down so a screenshot lands squarely mid-transition.
await page.addStyleTag({
  content: `@media (prefers-reduced-motion: no-preference) {
    ::view-transition-group(*), ::view-transition-old(*), ::view-transition-new(*) {
      animation-duration: 3s !important;
    }
  }`,
})

await page.click('.product-card:nth-child(3)')
for (const t of [500, 1200, 2000]) {
  await page.waitForTimeout(t === 500 ? 500 : 700)
  await page.screenshot({ path: `/tmp/vtcheck/1-forward-${t}ms.png` })
}
await page.waitForTimeout(3000)
await page.screenshot({ path: '/tmp/vtcheck/2-detail.png' })

console.log('named elements:', JSON.stringify(await page.evaluate(() => window.__noneEls), null, 1))

await browser.close()

