import { chromium } from 'playwright'

const browser = await chromium.launch()
const ctx = await browser.newContext({ reducedMotion: 'no-preference', viewport: { width: 1000, height: 700 } })
const page = await ctx.newPage()
await page.goto('http://localhost:3123', { waitUntil: 'networkidle' })

await page.addStyleTag({
  content: `::view-transition-group(*), ::view-transition-old(*), ::view-transition-new(*) {
    animation-duration: 4s !important;
  }`,
})

await page.click('.product-card:nth-child(3)')
await page.waitForTimeout(1000)

const probe = await page.evaluate(() => {
  const NAME = 'product-image-wireless-headphones'
  const read = (pseudo) => {
    const s = getComputedStyle(document.documentElement, pseudo)
    return {
      pseudo,
      width: s.width,
      height: s.height,
      objectFit: s.objectFit,
      inlineSize: s.inlineSize,
      blockSize: s.blockSize,
      position: s.position,
      animationName: s.animationName,
      animationDuration: s.animationDuration,
    }
  }
  return [
    read(`::view-transition-group(${NAME})`),
    read(`::view-transition-image-pair(${NAME})`),
    read(`::view-transition-old(${NAME})`),
    read(`::view-transition-new(${NAME})`),
  ]
})

console.log(JSON.stringify(probe, null, 1))
await browser.close()

